"use client";

// features/notes/hooks/useNoteAccess.ts
//
// The ONE answer to "can I edit this note?" for every notes surface.
//
// Composes the canonical access primitive (`useAccess` → `get_resource_access`)
// with what Redux already knows, so the common cases never hit the RPC:
//   - my own note (created_by === me, or a client-only autogenerated note) → edit
//   - a shared-with-me note (flagged by `fetchSharedNotesList`) → level from
//     its iam.permissions grant, already in the record
//   - anything else non-owned (e.g. opened by direct link) → resolve via the
//     `get_resource_access` RPC
//
// This is the PROACTIVE half of the read-only protection: editors render
// read-only + a banner instead of letting a viewer type into a note whose
// saves RLS will silently reject. The REACTIVE half (loud save failures in
// utils/writeErrors.ts) backstops any path that slips through.

import { useAppSelector } from "@/lib/redux/hooks";
import { useAccess } from "@/utils/permissions/access";
import {
  canEditAccess,
  type AccessLevel,
} from "@/utils/permissions/access-core";
import type { RootState } from "@/lib/redux/store";
import { selectNoteById } from "../redux/selectors";
import type { NoteRecord } from "../redux/notes.types";

export interface NoteAccess {
  /** True until ownership/level is known. Editors stay editable while
   *  loading (no read-only flash for owners); the loud-save backstop covers
   *  the brief window. */
  loading: boolean;
  /** True when the current user must NOT edit — render read-only UI. */
  readOnly: boolean;
  isOwner: boolean;
  /** True when the note reached the store via the shared-with-me list. */
  isSharedWithMe: boolean;
  /** Owner identity for shared notes (email from the share grant list). */
  ownerEmail: string | null;
  level: AccessLevel;
}

const selectNoRecord = (_state: RootState): NoteRecord | undefined => undefined;

export function useNoteAccess(noteId: string | null | undefined): NoteAccess {
  const myId = useAppSelector((s) => s.userAuth.id);
  const record = useAppSelector(
    noteId ? selectNoteById(noteId) : selectNoRecord,
  );

  const createdBy = record?.created_by ?? null;
  const ownsLocally = Boolean(
    record && myId && (record._isAutogenerated || createdBy === myId),
  );
  const sharedLevel = record?._sharedWithMe
    ? (record._sharedMeta?.permissionLevel ?? "viewer")
    : null;

  // RPC only for the residual case: a real, non-owned, un-flagged note
  // (typically opened via a direct /notes/[id] link to a shared note).
  const needsRpc = Boolean(
    noteId && record && myId && !ownsLocally && !sharedLevel,
  );
  const rpc = useAccess(
    needsRpc ? "note" : undefined,
    needsRpc ? (noteId ?? undefined) : undefined,
  );

  let level: AccessLevel;
  let loading: boolean;
  if (ownsLocally) {
    level = "admin";
    loading = false;
  } else if (sharedLevel) {
    level =
      sharedLevel === "viewer"
        ? "view"
        : sharedLevel === "editor"
          ? "edit"
          : "admin";
    loading = false;
  } else if (needsRpc) {
    level = rpc.level;
    loading = rpc.loading;
  } else {
    // Record (or session) not hydrated yet — unknown. Stay editable, report
    // loading; the reactive save guard screams if a write is actually blocked.
    level = "edit";
    loading = Boolean(noteId);
  }

  const isOwner = ownsLocally || (needsRpc && !rpc.loading && rpc.isOwner);

  return {
    loading,
    readOnly: !loading && Boolean(record) && !isOwner && !canEditAccess(level),
    isOwner,
    isSharedWithMe: Boolean(record?._sharedWithMe),
    ownerEmail: record?._sharedMeta?.ownerEmail ?? null,
    level,
  };
}
